def f(a, b, /, c, d, *, e, f):
    return (a, b, c, d, e, f)

print(f(1, 2, 3, d=4, e=5, f=6))
print(f(1, 2, c=3, d=4, e=5, f=6))

try:
    f(a=1, b=2, c=3, d=4, e=5, f=6)   # a, b are positional-only
except TypeError as ex:
    print("TypeError:", ex)

try:
    f(1, 2, 3, 4, 5, 6)   # e, f are keyword-only
except TypeError as ex:
    print("TypeError:", ex)
